/// Represents a closed interval [min, max].
#[derive(Debug, Clone, PartialEq)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    /// Creates a new Interval, asserting that min < max.
    pub fn new(min: f64, max: f64) -> Self {
        assert!(
            min < max,
            "Interval::new requires min < max, got min = {}, max = {}",
            min,
            max
        );
        Interval { min, max }
    }
}

/// Descriptor for a Chebyshev polynomial.
#[derive(Debug, Clone, PartialEq)]
pub struct ChebyshevPoly {
    /// Polynomial coefficients in increasing degree order.
    pub coeffs: Vec<i32>,
    /// Domain interval, must satisfy domain.min < domain.max.
    pub domain: Interval,
    /// Window interval, must satisfy window.min < window.max.
    pub window: Interval,
}

/// Constructs a Chebyshev polynomial descriptor from an input list of i8 coefficients.
/// 
/// # Panics
///
/// Panics if `coef` is empty or if the intervals are not valid (min >= max).
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Ensure input is non-empty
    assert!(
        !coef.is_empty(),
        "Coefficient vector must be non-empty"
    );

    // Convert coefficients from i8 to i32
    let coeffs_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();

    // Default domain and window intervals are both [-1.0, 1.0]
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);

    ChebyshevPoly {
        coeffs: coeffs_i32,
        domain,
        window,
    }
}

